package com.hbm.client.silex;
import com.hbm.machine.silex.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class SilexReiPlugin implements REIClientPlugin {
 static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","silex");@Override public void registerCategories(CategoryRegistry event){event.add(new Category());event.addWorkstations(TYPE,EntryStacks.of(SilexContent.ITEM.get()));}@Override public void registerScreens(me.shedaniel.rei.api.client.registry.screen.ScreenRegistry event){event.registerContainerClickArea(new Rectangle(39,60,60,50),SilexScreen.class,TYPE);}@Override public void registerDisplays(DisplayRegistry event){for(var recipe:SilexRecipes.recipes(event.getRecipeManager()))event.add(new Display(recipe));}
 static final class Display extends BasicDisplay{final SilexRecipe recipe;Display(SilexRecipe recipe){super(List.of(EntryIngredient.of(SilexViews.inputs(recipe).stream().map(EntryStacks::of).toList())),recipe.choices().stream().map(c->EntryIngredient.of(EntryStacks.of(c.stack()))).toList());this.recipe=recipe;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("jei.hbm.silex");}@Override public Renderer getIcon(){return EntryStacks.of(SilexContent.ITEM.get());}@Override public int getDisplayWidth(Display display){return 176;}@Override public int getDisplayHeight(){return 83;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){var widgets=new ArrayList<Widget>();widgets.add(Widgets.createDrawableWidget((g,x,y,partial)->SilexViews.draw(display.recipe,g,bounds.x,bounds.y)));widgets.add(Widgets.createSlot(new Point(bounds.x+12,bounds.y+24)).entries(display.getInputEntries().getFirst()).disableBackground().markInput());var positions=SilexViews.outputs(display.recipe);for(int i=0;i<positions.length;i++)widgets.add(Widgets.createSlot(new Point(bounds.x+positions[i][0],bounds.y+positions[i][1])).entries(display.getOutputEntries().get(i)).disableBackground().markOutput());return widgets;}}
}
